@namespace sv_b7a76f4a2a014f469c8acec2ca6fc2f7.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick" style="border:1px solid #ddd; border-radius:8px; padding:1rem; cursor:pointer; display:flex; flex-direction:column; gap:0.5rem;">
    <div class="product-image-placeholder" style="background:#f0f0f0; height:150px; display:flex; align-items:center; justify-content:center; border-radius:4px;">
        <span style="color:#999;">@Product.Name</span>
    </div>
    <h4 style="margin:0;">@Product.Name</h4>
    <p style="margin:0; font-weight:bold; color:#2a7ae2;">@Product.Price.ToString("C")</p>
    <span>@GetStarRating(Product.Rating)</span>
    @if (!Product.InStock)
    {
        <span class="out-of-stock-badge" style="background:#f44336; color:white; padding:2px 8px; border-radius:4px; font-size:0.8rem; align-self:flex-start;">Out of Stock</span>
    }
    <button class="add-to-cart-btn" disabled="@(!Product.InStock)" @onclick="HandleAddToCart" @onclick:stopPropagation="true"
        style="margin-top:auto; padding:0.5rem; border:none; border-radius:4px; background:@(Product.InStock ? "#4CAF50" : "#ccc"); color:white; cursor:@(Product.InStock ? "pointer" : "not-allowed");">
        Add to Cart
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

@namespace sv_b7a76f4a2a014f469c8acec2ca6fc2f7.Components.Pages.Catalog

@if (Products is null || Products.Count == 0)
{
    <div class="empty-state" style="text-align:center; padding:3rem; color:#666;">
        <p>No products found matching your criteria.</p>
    </div>
}
else
{
    <div class="product-grid" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(240px, 1fr)); gap:1.5rem;">
        @foreach (var product in Products)
        {
            <ProductCard Product="product" OnSelected="OnProductSelected" OnAddToCart="OnAddToCart" />
        }
    </div>
}

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = new();

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@namespace sv_b7a76f4a2a014f469c8acec2ca6fc2f7.Components.Pages.Catalog

<div class="catalog-filters" style="display:flex; flex-direction:column; gap:1rem;">
    <h3 style="margin:0;">Filters</h3>

    <fieldset style="border:1px solid #ddd; border-radius:4px; padding:0.75rem;">
        <legend>Categories</legend>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <label style="display:block; margin-bottom:0.25rem;">
                    <input type="checkbox" checked="@IsSelected(category)" @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                    @category
                </label>
            }
        }
    </fieldset>

    <fieldset style="border:1px solid #ddd; border-radius:4px; padding:0.75rem;">
        <legend>Price Range</legend>
        <label style="display:block; margin-bottom:0.5rem;">
            Min:
            <input type="number" min="0" step="0.01" value="@_minPrice" @onchange="e => _minPrice = ParseDecimal(e.Value)" style="width:100%; padding:4px;" />
        </label>
        <label style="display:block;">
            Max:
            <input type="number" min="0" step="0.01" value="@_maxPrice" @onchange="e => _maxPrice = ParseDecimal(e.Value)" style="width:100%; padding:4px;" />
        </label>
    </fieldset>

    <label style="display:flex; align-items:center; gap:0.5rem;">
        <input type="checkbox" checked="@_inStockOnly" @onchange="e => _inStockOnly = (bool)e.Value!" />
        In Stock Only
    </label>

    <button @onclick="ApplyFilters" style="padding:0.5rem; background:#2a7ae2; color:white; border:none; border-radius:4px; cursor:pointer;">
        Apply Filters
    </button>
    <button @onclick="ClearFilters" style="padding:0.5rem; background:#eee; color:#333; border:1px solid #ccc; border-radius:4px; cursor:pointer;">
        Clear Filters
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = new();

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !_selectedCategories.Contains(category))
            _selectedCategories.Add(category);
        else if (!isChecked)
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_b7a76f4a2a014f469c8acec2ca6fc2f7.Components.Pages.Catalog

<div class="catalog-toolbar" style="display:flex; justify-content:space-between; align-items:center; padding:0.75rem 0; border-bottom:1px solid #eee; margin-bottom:1rem;">
    <div>
        <label>
            Sort by:
            <select value="@SortBy" @onchange="HandleSortChange" style="padding:4px 8px; border-radius:4px; border:1px solid #ccc;">
                <option value="price_asc">Price: Low to High</option>
                <option value="price_desc">Price: High to Low</option>
                <option value="name_asc">Name: A-Z</option>
                <option value="rating_desc">Rating: Highest</option>
            </select>
        </label>
    </div>
    <div style="color:#666; font-size:0.9rem;">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
        else
        {
            <span>No products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChange(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_b7a76f4a2a014f469c8acec2ca6fc2f7.Components.Pages.Catalog

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" style="display:flex; justify-content:center; align-items:center; gap:0.5rem; margin-top:1.5rem;">
        <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
            style="padding:0.4rem 0.8rem; border:1px solid #ccc; border-radius:4px; cursor:@(CurrentPage <= 1 ? "not-allowed" : "pointer"); background:white;">
            Previous
        </button>

        @foreach (var page in GetPageNumbers())
        {
            <button @onclick="() => GoToPage(page)"
                style="padding:0.4rem 0.8rem; border:1px solid @(page == CurrentPage ? "#2a7ae2" : "#ccc"); border-radius:4px; cursor:pointer; background:@(page == CurrentPage ? "#2a7ae2" : "white"); color:@(page == CurrentPage ? "white" : "#333");">
                @page
            </button>
        }

        <button disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
            style="padding:0.4rem 0.8rem; border:1px solid #ccc; border-radius:4px; cursor:@(CurrentPage >= TotalPages ? "not-allowed" : "pointer"); background:white;">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        // Show up to 7 page numbers centered around current page
        int start = Math.Max(1, CurrentPage - 3);
        int end = Math.Min(TotalPages, start + 6);
        start = Math.Max(1, end - 6);

        for (int i = start; i <= end; i++)
            yield return i;
    }
}

@page "/catalog"
@namespace sv_b7a76f4a2a014f469c8acec2ca6fc2f7.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-page" style="display:flex; gap:2rem; padding:1rem;">
    @* Left Sidebar *@
    <aside style="width:25%; min-width:200px;">
        @if (_categories is not null)
        {
            <CatalogFilters Categories="_categories" OnFilterApplied="HandleFilterApplied" OnFilterCleared="HandleFilterCleared" />
        }
    </aside>

    @* Main Content *@
    <main style="width:75%;">
        @if (_error is not null)
        {
            <div class="error-state" style="background:#ffebee; color:#c62828; padding:1rem; border-radius:4px; margin-bottom:1rem;">
                <p>Error loading products: @_error</p>
                <button @onclick="LoadProducts" style="padding:0.4rem 0.8rem; border:none; border-radius:4px; background:#c62828; color:white; cursor:pointer;">
                    Retry
                </button>
            </div>
        }
        else if (_loading)
        {
            <div class="loading-state" style="text-align:center; padding:3rem; color:#666;">
                <p>Loading products...</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy" TotalCount="@(_result?.TotalCount ?? 0)"
                Page="@_currentPage" PageSize="@PageSize" OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="@(_result?.Items ?? new())" OnProductSelected="HandleProductSelected" OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="@_currentPage" TotalPages="@TotalPages" OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private const int PageSize = 12;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private bool _loading = true;
    private string? _error;

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 0
        : (int)Math.Ceiling((double)_result.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _loading = false;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

