arguments.old_str:
@foreach (var page in GetPageNumbers())
{
    <button @onclick="() => GoToPage(page)"
        style="padding:0.4rem 0.8rem; border:1px solid @(page == CurrentPage ? "#2a7ae2" : "#ccc"); border-radius:4px; cursor:pointer; background:@(page == CurrentPage ? "#2a7ae2" : "white"); color:@(page == CurrentPage ? "white" : "#333");">
        @page
    </button>
}

